arguments.command:
mkdir -p /tmp/SupportB60 && cd /tmp/SupportB60 && python3 -B -c "import re,pathlib; files={'P01':'p01.txt','P02':'p02.txt','P03':'p03.html','P04':'p04.html','P05':'p05.html','P06':'p06.html','P06W':'p06w.html','P07':'p07.html','P08':'p08.txt'}; needles={'P01':['mass-produced','twenty thousand'],'P02':['Also like yantra','Somdet To'],'P03':['Throughout all the East','iaspis'],'P04':['apotropaic marks','fireplaces'],'P05':['main panel','Lilith'],'P06':['An amulet in this shape','regeneration'],'P06W':['An amulet in this shape','regeneration'],'P07':['protective nature','Agathodaimon'],'P08':['Other amulets','adjuration formula']};
for label,name in files.items():
 t=pathlib.Path(name).read_text(errors='replace');
 if name.endswith('.html'): t=re.sub(r'(?s)<[^>]+>',' ',t); t=re.sub(r'\\s+',' ',t)
 print('\\n###',label,'chars',len(t));
 for nd in needles[label]:
  i=t.lower().find(nd.lower());
  if i>=0: print(nd,repr(t[max(0,i-450):i+950]));
  else: print(nd,'NOT FOUND')"

